style.css:
@-moz-document domain("do.sevsu.ru") {
html {
  	background: #121212;
	}

	.container-fluid {
  	background: #121212;
	}

	section {
  	background: #121212;
	}

	p {
    font-size: 16px; /* px значит 'пиксели': базовый шрифт будет 10 пикселей в высоту  */
		font-family: Arial;
	}

	.activity {
  	background: #383838;
  	border-radius: 8px;
  	box-shadow: inset 0 0 0 0.5px rgba(255,255,255,.5);
	}
	div [class = "card-body p-3"] {
  	background: #2f2f2f;
  	border-radius: 8px;
  	box-shadow: inset 0 0 0 0.5px rgba(255,255,255,.5);
	}

	.instancename {
  	text-decoration: none;
  	color: #dfdfdf;
	}
	.img-responsive {
  	border-radius: 8px;
	}
}
